var n=`0327-salade-nicoise`;var t=`world-0327`;var a=`FR`;var o=`western-europe`;var s=4;var r=36;var l={en:`Salade Niçoise`,ua:`Салат нісуаз`};var g={en:`A traditional France dish made with chicken egg, new potato, green beans, tomato. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: куряче яйце, молода картопля, стручкова квасоля, помідор. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,3,`pcs`]]},{en:`Cook the listed ingredients in simmering water for about 15 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 15 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:15,i:[[`new-potato`,330,`g`],[`green-beans`,220,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`tomato`,450,`g`],[`cucumber`,230,`g`],[`red-onion`,90,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:4,i:[[`canned-tuna`,230,`g`],[`anchovy-fillets`,55,`g`],[`kalamata-olives`,90,`g`],[`extra-virgin-olive-oil`,65,`ml`],[`lemon-juice`,25,`ml`]]}];var c={slug:n,id:t,country:`FR`,region:o,servings:4,minutes:36,title:l,text:g,steps:d};export{a as country,c as default,t as id,r as minutes,o as region,s as servings,n as slug,d as steps,g as text,l as title};